keys=['step','val/test_score/openai/gsm8k','critic/score/mean','response_length/mean','response_length/clip_ratio','actor/entropy_loss','critic/kl','actor/pg_loss','actor/pg_clipfrac','actor/ppo_kl','actor/grad_norm','actor/parameter_probe_change','actor/lr_used','actor/scheduler_epoch','actor/optimizer_step_max','timing_s/step']
print('\t'.join(keys))
for m in ms:
 print('\t'.join(f'{m[k]:.6g}' if isinstance(m.get(k),(int,float)) else '-' for k in keys))
print('Prompt maxima:',max(m.get('prompt_length/max',0) for m in ms),'max clip:',max(m.get('prompt_length/clip_ratio',0) for m in ms))
for name in ['dataset','validation','rewards','objective']:
 rs=[json.loads(l) for l in (Path('observed_run')/(name+'.jsonl')).read_text().splitlines()]
 print('\n',name,'records',len(rs))
 if name=='dataset':
  print('splits',{s:sum(r['split']==s for r in rs) for s in {r['split'] for r in rs}})
  print('label mismatches',sum(r['canonical_answer']!=r['training_answer'] for r in rs))
 if name in ['validation','rewards']:
  d=defaultdict(list)
  for r in rs:d[r['trainer_step']].append(r)
  for step,rows in d.items():
   if name=='rewards' and step not in [1,2,3,5,10,15,20,25,30]:continue
   print('step',step,'n',len(rows),'unique indices',len({r['index'] for r in rows}),'score',sum(r['score'] for r in rows)/len(rows),'boxed',sum('\\boxed{' in r['response'] for r in rows),'chars',round(statistics.mean(len(r['response']) for r in rows),1))
  if name=='rewards':print('score/exact mismatches',sum(r['score']!=r['exact'] for r in rs),'label mismatches',sum(r['ground_truth']!=r['canonical_answer'] for r in rs))
PY",max_output_tokens:5500}),
  tools.exec_command({cmd:"nl -ba verl/utils/dataset/rl_dataset.py | sed -n '40,260p'",max_output_tokens:4200}),
